@@ -6,12 +6,66 @@ export interface Record {
   warns: readonly string[];
 }

+const deduplicateEntries = (entries: readonly string[]): string[] => {
+  if (entries.length <= 1) return [...entries];
+
+  // Extract normalized tokens for similarity comparison (skip stopwords)
+  const stopwords = new Set(['that', 'this', 'with', 'will', 'have', 'from', 'more', 'one']);
+  const getTokens = (entry: string): Set<string> => {
+    return new Set(
+      entry
+        .toLowerCase()
+        .split(/\s+/)
+        .filter(w => w.length > 2 && !stopwords.has(w))
+    );
+  };
+
+  // Calculate Jaccard similarity between two entries
+  const similarity = (a: string, b: string): number => {
+    const tokensA = getTokens(a);
+    const tokensB = getTokens(b);
+    const intersection = new Set([...tokensA].filter(t => tokensB.has(t)));
+    const union = new Set([...tokensA, ...tokensB]);
+    return intersection.size / union.size;
+  };
+
+  // Group similar entries (threshold: 30% token overlap)
+  const groups: string[][] = [];
+  const assigned = new Set<number>();
+
+  for (let i = 0; i < entries.length; i++) {
+    if (assigned.has(i)) continue;
+
+    const group = [entries[i]];
+    assigned.add(i);
+
+    for (let j = i + 1; j < entries.length; j++) {
+      if (assigned.has(j) || similarity(entries[i], entries[j]) < 0.3) continue;
+      group.push(entries[j]);
+      assigned.add(j);
+    }
+
+    groups.push(group);
+  }
+
+  // From each group, pick the shortest entry (usually most concise/direct)
+  return groups.map(group =>
+    group.reduce((best, current) =>
+      current.length < best.length ? current : best
+    )
+  );
+};
+
 export const project = (records: readonly Record[]): string => {
   const lines: string[] = [];
   for (const record of records) {
-    for (const entry of record.ruledOut) lines.push(`- ruled out: ${entry}`);
-    for (const limit of record.limits) lines.push(`- limit: ${limit}`);
-    for (const warn of record.warns) lines.push(`- warn: ${warn}`);
+    const deduplicatedRuledOut = deduplicateEntries([...record.ruledOut]);
+    const deduplicatedLimits = deduplicateEntries([...record.limits]);
+    const deduplicatedWarns = deduplicateEntries([...record.warns]);
+
+    for (const entry of deduplicatedRuledOut) lines.push(`- ruled out: ${entry}`);
+    for (const limit of deduplicatedLimits) lines.push(`- limit: ${limit}`);
+    for (const warn of deduplicatedWarns) lines.push(`- warn: ${warn}`);
   }
   return lines.join("\n");
 };
